{
  "metric": "avg_total_amount",
  "target_window": "2025-01-20",
  "baseline_window": "2025-01-06, 2025-01-13, 2025-01-27",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "The average total amount per yellow taxi trip on Monday 2025-01-20 was higher than the average of the other three Mondays in January 2025 (2025-01-06, 2025-01-13, 2025-01-27).",
      "support_if": "avg_total_amount on 2025-01-20 > mean(avg_total_amount on 2025-01-06, 2025-01-13, 2025-01-27) by a meaningful margin (e.g., >5%).",
      "refute_if": "avg_total_amount on 2025-01-20 is within 5% of the baseline Mondays' average."
    },
    {
      "id": "H1",
      "kind": "holiday",
      "statement": "Monday 2025-01-20 was Martin Luther King Jr. Day (a federal holiday), which changed the passenger mix (e.g., more tourists, fewer commuters) and/or trip characteristics (longer trips, higher fares) compared to regular Mondays.",
      "support_if": "us_holidays shows a federal holiday on 2025-01-20 (MLK Day) and not on the other Mondays; trip count on 2025-01-20 differs significantly from baseline Mondays.",
      "refute_if": "2025-01-20 is not a holiday, or trip count and avg_total_amount patterns match baseline Mondays."
    },
    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather on 2025-01-20 (e.g., snow, rain, extreme cold) caused longer trips, more surcharges, or a shift to taxi from other modes, raising avg_total_amount.",
      "support_if": "nyc_weather_daily shows precipitation, snowfall, or extreme temperatures on 2025-01-20 that are absent on baseline Mondays; avg_trip_distance also higher on 2025-01-20.",
      "refute_if": "Weather on 2025-01-20 is similar to baseline Mondays (no precipitation, similar temps)."
    },
    {
      "id": "H3",
      "kind": "fare_mix",
      "statement": "The fare composition on 2025-01-20 shifted toward higher-fare components (e.g., more tolls, tips, surcharges, or longer distances) compared to baseline Mondays.",
      "support_if": "avg_trip_distance on 2025-01-20 is higher than baseline; if trip-level data were available, tolls/tips/surcharges would be higher. With daily aggregates, we check avg_trip_distance and trip count as proxies.",
      "refute_if": "avg_trip_distance and trip count on 2025-01-20 are in line with baseline Mondays."
    },
    {
      "id": "H4",
      "kind": "zone_mix",
      "statement": "The geographic mix of trips on 2025-01-20 shifted toward zones with higher average fares (e.g., more airport trips, Manhattan core) compared to baseline Mondays.",
      "support_if": "If zone-level data were available, we would see a higher share of trips from high-fare zones on 2025-01-20. With current tables, we can only infer from distance and count proxies.",
      "refute_if": "No proxy evidence of zone mix shift (distance, count stable)."
    },
    {
      "id": "H5",
      "kind": "data_quality",
      "statement": "The spike on 2025-01-20 is an artifact of data quality issues (e.g., missing trips, duplicate records, fare calculation errors) rather than a real change.",
      "support_if": "Trip count on 2025-01-20 is anomalously low or high vs baseline; avg_total_amount is an extreme outlier (>3 std dev from baseline mean).",
      "refute_if": "Trip count and avg_total_amount on 2025-01-20 are within normal variation of baseline Mondays."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Get avg_total_amount, trips, avg_trip_distance for target Monday 2025-01-20 and baseline Mondays 2025-01-06, 2025-01-13, 2025-01-27. Compute target vs baseline average.",
      "tables": [
        "whybot.yellow_daily"
      ]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Check if 2025-01-20 is a federal holiday (MLK Day) and confirm other Mondays are not holidays. Join yellow_daily with us_holidays on trip_date=holiday_date for the four Mondays.",
      "tables": [
        "whybot.yellow_daily",
        "whybot.us_holidays"
      ]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Get weather (prcp_mm, snow_mm, tmax_c, tmin_c) for 2025-01-20 and the three baseline Mondays. Compare for anomalies.",
      "tables": [
        "whybot.nyc_weather_daily"
      ]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Compare avg_trip_distance and trips on 2025-01-20 vs baseline Mondays as proxies for fare mix changes (longer trips, different volume).",
      "tables": [
        "whybot.yellow_daily"
      ]
    },
    {
      "hypothesis_id": "H5",
      "purpose": "Assess data quality: check if trips on 2025-01-20 is an outlier (e.g., <50% or >150% of baseline mean) and if avg_total_amount is >3 std dev from baseline mean.",
      "tables": [
        "whybot.yellow_daily"
      ]
    }
  ],
  "rationale": "H0 quantifies the metric jump. H1 tests the holiday hypothesis (MLK Day). H2 tests weather impact. H3 uses available daily aggregates (distance, count) as proxies for fare mix. H4 (zone_mix) cannot be directly tested with current tables (no zone-level daily data), so we note it and rely on proxies. H5 checks for data quality issues. All queries use only catalog tables and stay within the 2024-04-01..2025-02-28 window."
}

{
  "sql": "SELECT y.trip_date, MAX(CASE WHEN y.trip_date = DATE '2025-01-20' THEN y.avg_total_amount END) AS target_avg_total_amount, AVG(CASE WHEN y.trip_date <> DATE '2025-01-20' THEN y.avg_total_amount END) AS baseline_avg_total_amount FROM whybot.yellow_daily y JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE d.d_dow = 1 AND y.trip_date BETWEEN DATE '2025-01-01' AND DATE '2025-01-31' GROUP BY y.trip_date ORDER BY y.trip_date",
  "tables_used": ["whybot.yellow_daily", "TPCDS_DB.date_dim"],
  "note": "Compares target Monday 2025-01-20 avg total amount against other Mondays in January 2025 using conditional aggregation; avoids self-joining us_holidays per Zetaris quirks."
}

